-- P1-02 P5 AW17-20 Binomial pack: BIN-02/03.
-- Original iClub-authored content only; governed publication; legacy questions remain draft + inactive.
begin;
insert into private.exam_prep_content_versions(program_version_id,content_version,component_code,release_label,status,source_policy)
select pv.id,'p5_aw17_20_binomial_v1','P5','P5 AW17-20 Binomial probabilities and parameters','draft','Original iClub content only; Cambridge 9709 official syllabus defines scope; Complete Probability & Statistics 1 is mapping/teaching reference only; no protected source wording copied.'
from private.exam_prep_program_versions pv where pv.program_key='math_as_p1_p5' and pv.version_key='p1_p5_canonical_v1_0'
on conflict(program_version_id,content_version) do nothing;

with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw17_20_binomial_v1' and component_code='P5' and status='draft'), src(skill,k,role,diff,qen,qru,quz,o_en,o_ru,o_uz,ans,een,eru,euz,secs) as (values
('P5-BIN-02','P5BIN02-D01','diagnostic','medium','If X~B(5,0.2), find P(X=0).','Если X~B(5;0,2), найдите P(X=0).','X~B(5,0.2) bo‘lsa, P(X=0) ni toping.','["0.32768","0.20000","0.40960","0.67232"]','["0,32768","0,20000","0,40960","0,67232"]','["0.32768","0.20000","0.40960","0.67232"]','A','P(X=0)=(0.8)^5=0.32768.','P(X=0)=(0,8)^5=0,32768.','P(X=0)=(0.8)^5=0.32768.',45),
('P5-BIN-02','P5BIN02-L01','learning','easy','If X~B(4,0.5), find P(X=2).','Если X~B(4;0,5), найдите P(X=2).','X~B(4,0.5) bo‘lsa, P(X=2) ni toping.','["0.375","0.250","0.500","0.625"]','["0,375","0,250","0,500","0,625"]','["0.375","0.250","0.500","0.625"]','A','P(X=2)=C(4,2)(0.5)^2(0.5)^2=6/16=0.375.','P(X=2)=C(4,2)(0,5)^4=0,375.','P(X=2)=C(4,2)(0.5)^4=0.375.',45),
('P5-BIN-02','P5BIN02-L02','learning','medium','If X~B(3,0.2), find P(X≥1).','Если X~B(3;0,2), найдите P(X≥1).','X~B(3,0.2) bo‘lsa, P(X≥1) ni toping.','["0.488","0.512","0.096","0.800"]','["0,488","0,512","0,096","0,800"]','["0.488","0.512","0.096","0.800"]','A','Use the complement: 1−P(X=0)=1−0.8^3=0.488.','Используем дополнение: 1−0,8^3=0,488.','To‘ldiruvchidan: 1−0.8^3=0.488.',45),
('P5-BIN-02','P5BIN02-L03','learning','medium','If X~B(6,0.3), find P(X≤1).','Если X~B(6;0,3), найдите P(X≤1).','X~B(6,0.3) bo‘lsa, P(X≤1) ni toping.','["0.420175","0.117649","0.302526","0.579825"]','["0,420175","0,117649","0,302526","0,579825"]','["0.420175","0.117649","0.302526","0.579825"]','A','P(X≤1)=0.7^6+6(0.3)(0.7)^5=0.420175.','P(X≤1)=0,7^6+6(0,3)(0,7)^5=0,420175.','P(X≤1)=0.7^6+6(0.3)(0.7)^5=0.420175.',60),
('P5-BIN-02','P5BIN02-R01','retest','easy','If X~B(5,0.5), find P(X=5).','Если X~B(5;0,5), найдите P(X=5).','X~B(5,0.5) bo‘lsa, P(X=5) ni toping.','["0.03125","0.15625","0.50000","0.96875"]','["0,03125","0,15625","0,50000","0,96875"]','["0.03125","0.15625","0.50000","0.96875"]','A','P(X=5)=(0.5)^5=1/32=0.03125.','P(X=5)=(0,5)^5=0,03125.','P(X=5)=(0.5)^5=0.03125.',35),
('P5-BIN-02','P5BIN02-R02','retest','medium','If X~B(4,0.25), find P(X=0).','Если X~B(4;0,25), найдите P(X=0).','X~B(4,0.25) bo‘lsa, P(X=0) ni toping.','["0.31640625","0.00390625","0.421875","0.68359375"]','["0,31640625","0,00390625","0,421875","0,68359375"]','["0.31640625","0.00390625","0.421875","0.68359375"]','A','P(X=0)=(0.75)^4=0.31640625.','P(X=0)=(0,75)^4=0,31640625.','P(X=0)=(0.75)^4=0.31640625.',40),
('P5-BIN-02','P5BIN02-M01','mixed','medium','If X~B(4,0.5), find P(1≤X≤3).','Если X~B(4;0,5), найдите P(1≤X≤3).','X~B(4,0.5) bo‘lsa, P(1≤X≤3) ni toping.','["0.875","0.750","0.625","0.9375"]','["0,875","0,750","0,625","0,9375"]','["0.875","0.750","0.625","0.9375"]','A','Use the complement of X=0 or 4: 1−2(1/16)=14/16=0.875.','Вычтем случаи X=0 и X=4: 1−2/16=0,875.','X=0 va X=4 ni ayiramiz: 1−2/16=0.875.',50),

('P5-BIN-03','P5BIN03-D01','diagnostic','medium','If X~B(20,0.3), find Var(X).','Если X~B(20;0,3), найдите Var(X).','X~B(20,0.3) bo‘lsa, Var(X) ni toping.','["4.2","6","1.8","14"]','["4,2","6","1,8","14"]','["4.2","6","1.8","14"]','A','Var(X)=np(1−p)=20(0.3)(0.7)=4.2.','Var(X)=20(0,3)(0,7)=4,2.','Var(X)=20(0.3)(0.7)=4.2.',45),
('P5-BIN-03','P5BIN03-L01','learning','easy','If X~B(10,0.2), find E(X).','Если X~B(10;0,2), найдите E(X).','X~B(10,0.2) bo‘lsa, E(X) ni toping.','["2","1.6","8","0.2"]','["2","1,6","8","0,2"]','["2","1.6","8","0.2"]','A','E(X)=np=10(0.2)=2.','E(X)=np=2.','E(X)=np=2.',35),
('P5-BIN-03','P5BIN03-L02','learning','medium','A binomial variable has E(X)=12 and p=0.4. Find n.','У биномиальной случайной величины E(X)=12 и p=0,4. Найдите n.','Binomial tasodifiy miqdor uchun E(X)=12 va p=0.4. n ni toping.','["30","4.8","12.4","48"]','["30","4,8","12,4","48"]','["30","4.8","12.4","48"]','A','np=12, so n=12/0.4=30.','np=12, поэтому n=30.','np=12, demak n=30.',40),
('P5-BIN-03','P5BIN03-L03','learning','medium','If X~B(20,p) and E(X)=5, find p.','Если X~B(20,p) и E(X)=5, найдите p.','X~B(20,p) va E(X)=5 bo‘lsa, p ni toping.','["0.25","0.20","4","15"]','["0,25","0,20","4","15"]','["0.25","0.20","4","15"]','A','20p=5, so p=0.25.','20p=5, поэтому p=0,25.','20p=5, demak p=0.25.',40),
('P5-BIN-03','P5BIN03-R01','retest','easy','If X~B(10,0.2), find Var(X).','Если X~B(10;0,2), найдите Var(X).','X~B(10,0.2) bo‘lsa, Var(X) ni toping.','["1.6","2","8","0.16"]','["1,6","2","8","0,16"]','["1.6","2","8","0.16"]','A','Var(X)=10(0.2)(0.8)=1.6.','Var(X)=1,6.','Var(X)=1.6.',35),
('P5-BIN-03','P5BIN03-R02','retest','medium','A binomial variable has n=25 and mean 10. Find p.','У биномиальной случайной величины n=25 и среднее 10. Найдите p.','Binomial tasodifiy miqdorda n=25 va o‘rtacha 10. p ni toping.','["0.4","0.6","2.5","15"]','["0,4","0,6","2,5","15"]','["0.4","0.6","2.5","15"]','A','25p=10, hence p=0.4.','25p=10, значит p=0,4.','25p=10, demak p=0.4.',40),
('P5-BIN-03','P5BIN03-M01','mixed','hard','A binomial variable has mean 8 and variance 4.8. Find n and p.','Биномиальная случайная величина имеет среднее 8 и дисперсию 4,8. Найдите n и p.','Binomial tasodifiy miqdorning o‘rtachasi 8 va dispersiyasi 4.8. n va p ni toping.','["n=20, p=0.4","n=16, p=0.5","n=10, p=0.8","n=25, p=0.32"]','["n=20, p=0,4","n=16, p=0,5","n=10, p=0,8","n=25, p=0,32"]','["n=20, p=0.4","n=16, p=0.5","n=10, p=0.8","n=25, p=0.32"]','A','Variance/mean=q=4.8/8=0.6, so p=0.4; then n=8/0.4=20.','Дисперсия/среднее=q=0,6, поэтому p=0,4 и n=20.','Dispersiya/o‘rtacha=q=0.6, demak p=0.4 va n=20.',65)
)
insert into public.questions(subject_id,topic,subtopic,difficulty,qtype,question_text,options_text,correct_answer,explanation,image_url,is_active,question_text_ru,question_text_uz,question_text_en,options_text_ru,options_text_uz,options_text_en,explanation_ru,explanation_uz,explanation_en,book_ref,time_limit_sec,quality_flag,quality_status)
select 5,'P5 Binomial Distribution',s.skill,s.diff,'mcq',s.qen,s.o_en,s.ans,s.een,null,false,s.qru,s.quz,s.qen,s.o_ru,s.o_uz,s.o_en,s.eru,s.euz,s.een,'ExamPrep:P5:p5_aw17_20_binomial_v1:'||s.k,s.secs,null,'draft' from cv cross join src s
where not exists(select 1 from public.questions q where q.book_ref='ExamPrep:P5:p5_aw17_20_binomial_v1:'||s.k);

with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw17_20_binomial_v1' and status='draft'), keys(skill,k,role) as (values
('P5-BIN-02','P5BIN02-D01','diagnostic'),('P5-BIN-02','P5BIN02-L01','learning'),('P5-BIN-02','P5BIN02-L02','learning'),('P5-BIN-02','P5BIN02-L03','learning'),('P5-BIN-02','P5BIN02-R01','retest'),('P5-BIN-02','P5BIN02-R02','retest'),('P5-BIN-02','P5BIN02-M01','mixed'),
('P5-BIN-03','P5BIN03-D01','diagnostic'),('P5-BIN-03','P5BIN03-L01','learning'),('P5-BIN-03','P5BIN03-L02','learning'),('P5-BIN-03','P5BIN03-L03','learning'),('P5-BIN-03','P5BIN03-R01','retest'),('P5-BIN-03','P5BIN03-R02','retest'),('P5-BIN-03','P5BIN03-M01','mixed'))
insert into private.exam_prep_question_content_meta(content_version_id,content_key,question_id,primary_skill_code,secondary_skill_codes,reserve_role,exposure_state,lifecycle_state,originality_attestation,provenance_note,official_scope_ref,coursebook_mapping_ref,copyright_status,qa_scope_status,qa_math_status,qa_language_status,qa_technical_status,diagnostic_rule_status,question_snapshot_md5)
select cv.id,k.k,q.id,k.skill,'{}'::text[],k.role,'withheld','draft','Original iClub-authored content; no protected source wording copied.','Authored for p5_aw17_20_binomial_v1 from canonical Binomial skill intent.','Cambridge 9709 2026-2027 v4; P5 5.4 Discrete random variables','Complete Probability & Statistics 1; Binomial distribution (mapping only)','pending','pending','pending','pending','pending',case when k.role='diagnostic' then 'pending' else 'not_applicable' end,
md5(concat_ws(chr(31),q.id::text,q.subject_id::text,coalesce(q.topic,''),coalesce(q.subtopic,''),coalesce(q.difficulty,''),coalesce(q.qtype,''),coalesce(q.question_text,''),coalesce(q.options_text,''),coalesce(q.correct_answer,''),coalesce(q.explanation,''),coalesce(q.image_url,''),coalesce(q.is_active::text,''),coalesce(q.question_text_ru,''),coalesce(q.question_text_uz,''),coalesce(q.question_text_en,''),coalesce(q.options_text_ru,''),coalesce(q.options_text_uz,''),coalesce(q.options_text_en,''),coalesce(q.explanation_ru,''),coalesce(q.explanation_uz,''),coalesce(q.explanation_en,''),coalesce(q.book_ref,''),coalesce(q.time_limit_sec::text,''),coalesce(q.quality_flag,''),coalesce(q.quality_status,'')))
from cv cross join keys k join public.questions q on q.book_ref='ExamPrep:P5:p5_aw17_20_binomial_v1:'||k.k
on conflict(content_version_id,content_key) do nothing;

with meta as (select m.id,m.content_key,m.primary_skill_code from private.exam_prep_question_content_meta m join private.exam_prep_content_versions cv on cv.id=m.content_version_id where cv.content_version='p5_aw17_20_binomial_v1' and m.reserve_role='diagnostic'), r(ckey,match,dcode,mtype,fen,fru,fuz,nen,nru,nuz) as (values
('P5BIN02-D01','B','uses_success_probability','concept','p=0.2 is the probability of one success, not the probability of zero successes in five trials.','p=0,2 — вероятность одного успеха, а не нуля успехов в пяти испытаниях.','p=0.2 bitta muvaffaqiyat ehtimoli, besh sinovda nol muvaffaqiyat ehtimoli emas.','For X=0, all five trials must fail.','Для X=0 все пять испытаний должны быть неудачными.','X=0 uchun besh sinovning barchasi muvaffaqiyatsiz bo‘lishi kerak.'),
('P5BIN02-D01','C','wrong_failure_power','method','0.4096=0.8^4 uses only four failures; n=5 requires five.','0,4096=0,8^4 учитывает только четыре неудачи; n=5 требует пять.','0.4096=0.8^4 faqat to‘rt muvaffaqiyatsizlik; n=5 uchun beshta kerak.','Match the exponent to n.','Сопоставьте показатель с n.','Darajani n bilan moslang.'),
('P5BIN02-D01','D','takes_complement','method','0.67232 is 1−P(X=0), the probability of at least one success.','0,67232 — это 1−P(X=0), вероятность хотя бы одного успеха.','0.67232 — 1−P(X=0), kamida bitta muvaffaqiyat ehtimoli.','Read whether the event is X=0 or X≥1.','Проверьте, требуется X=0 или X≥1.','Hodisa X=0 mi yoki X≥1 mi, tekshiring.'),
('P5BIN03-D01','B','uses_mean','concept','6=np is the mean, not the variance.','6=np — это среднее, а не дисперсия.','6=np o‘rtacha, dispersiya emas.','Use Var(X)=np(1−p).','Используйте Var(X)=np(1−p).','Var(X)=np(1−p) ni ishlating.'),
('P5BIN03-D01','C','uses_p_squared','method','The variance uses p(1−p), not p².','Дисперсия использует p(1−p), а не p².','Dispersiya p(1−p) ni ishlatadi, p² emas.','Compute q=1−p first.','Сначала найдите q=1−p.','Avval q=1−p ni toping.'),
('P5BIN03-D01','D','uses_nq','concept','14=n(1−p) is not a variance formula.','14=n(1−p) не является формулой дисперсии.','14=n(1−p) dispersiya formulasi emas.','Use npq.','Используйте npq.','npq ni ishlating.'))
insert into private.exam_prep_diagnostic_rules(content_meta_id,rule_version,answer_kind,answer_match,distractor_code,mistake_type,weak_skill_code,feedback_en,feedback_ru,feedback_uz,next_action_en,next_action_ru,next_action_uz,status,approved_at)
select meta.id,'drv1','mcq_option',r.match,r.dcode,r.mtype,meta.primary_skill_code,r.fen,r.fru,r.fuz,r.nen,r.nru,r.nuz,'approved',now() from r join meta on meta.content_key=r.ckey
on conflict(content_meta_id,rule_version,answer_kind,answer_match) do nothing;

with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw17_20_binomial_v1' and status='draft'), defs(task_key,skill,en,ru,uz,rubric,sen,sru,suz) as (values
('P5BIN02-W01','P5-BIN-02','Let X~B(8,0.25). Find P(X=0), P(X≥1), P(X=2), and P(1≤X≤2). Show where a complement is more efficient than direct summation.','Пусть X~B(8;0,25). Найдите P(X=0), P(X≥1), P(X=2) и P(1≤X≤2). Покажите, где дополнение эффективнее прямого суммирования.','X~B(8,0.25) bo‘lsin. P(X=0), P(X≥1), P(X=2) va P(1≤X≤2) ni toping. Qayerda to‘ldiruvchi usul samaraliroq ekanini ko‘rsating.','{"max_marks":11,"criteria":[{"id":"p0","marks":2,"rule":"Uses 0.75^8."},{"id":"complement","marks":2,"rule":"Uses 1−0.75^8 for P(X≥1)."},{"id":"p2","marks":3,"rule":"Uses C(8,2)(0.25)^2(0.75)^6."},{"id":"interval","marks":3,"rule":"Adds the X=1 and X=2 terms correctly."},{"id":"method","marks":1,"rule":"Explains complement efficiency for at least one success."}]}','Write the event first, then choose point-sum or complement.','Сначала запишите событие, затем выберите прямую сумму или дополнение.','Avval hodisani yozing, keyin to‘g‘ridan-to‘g‘ri yig‘indi yoki to‘ldiruvchini tanlang.'),
('P5BIN03-W01','P5-BIN-03','A binomial random variable has mean 9 and variance 6.3. Find p and n, then find the standard deviation. Explain why variance/mean reveals 1−p.','Биномиальная случайная величина имеет среднее 9 и дисперсию 6,3. Найдите p и n, затем стандартное отклонение. Объясните, почему отношение дисперсии к среднему даёт 1−p.','Binomial tasodifiy miqdorning o‘rtachasi 9, dispersiyasi 6.3. p va n ni, keyin standart og‘ishni toping. Nega dispersiya/o‘rtacha 1−p ni berishini tushuntiring.','{"max_marks":10,"criteria":[{"id":"ratio","marks":3,"rule":"Uses variance/mean=0.7=1−p."},{"id":"p","marks":2,"rule":"Obtains p=0.3."},{"id":"n","marks":2,"rule":"Uses np=9 to obtain n=30."},{"id":"sd","marks":2,"rule":"Obtains sqrt(6.3)."},{"id":"explanation","marks":1,"rule":"Explains npq/(np)=q."}]}','Use the two equations np=mean and npq=variance before solving.','Используйте np=mean и npq=variance до решения.','Yechishdan oldin np=mean va npq=variance tenglamalarini yozing.'))
insert into private.exam_prep_written_tasks(content_version_id,task_key,component_code,primary_skill_code,task_version,prompt_en,prompt_ru,prompt_uz,rubric_json,self_review_en,self_review_ru,self_review_uz,lifecycle_state,copyright_status,qa_math_status,qa_language_status,qa_technical_status,approved_at)
select cv.id,d.task_key,'P5',d.skill,'wtv1',d.en,d.ru,d.uz,d.rubric::jsonb,d.sen,d.sru,d.suz,'approved','pass','pass','pass','pass',now() from defs d cross join cv
on conflict(content_version_id,task_key,task_version) do nothing;

with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw17_20_binomial_v1' and status='draft'), defs(k,t,en,ru,uz) as (values
('p5_aw17_binomial_diagnostic','diagnostic','P5 AW17-20 Binomial diagnostic','Диагностика P5 AW17–20: биномиальная модель','P5 AW17–20 binomial diagnostikasi'),('p5_bin02_learning','learning','Binomial probabilities learning','Биномиальные вероятности: обучение','Binomial ehtimollar: o‘rganish'),('p5_bin03_learning','learning','Binomial mean and variance learning','Среднее и дисперсия binomial: обучение','Binomial o‘rtacha va dispersiya: o‘rganish'),('p5_bin02_retest','retest','BIN-02 delayed retest','BIN-02 отложенный ретест','BIN-02 kechiktirilgan retest'),('p5_bin03_retest','retest','BIN-03 delayed retest','BIN-03 отложенный ретест','BIN-03 kechiktirilgan retest'),('p5_aw17_binomial_mixed','mixed','P5 AW17-20 Binomial mixed transfer','P5 AW17–20: смешанный перенос binomial','P5 AW17–20 binomial mixed transfer'))
