with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw17_20_binomial_v1'), a as (select x.id,x.assessment_key from private.exam_prep_assessments x join cv on cv.id=x.content_version_id), m as (select x.content_key,x.question_id from private.exam_prep_question_content_meta x join cv on cv.id=x.content_version_id), w as (select x.id,x.task_key from private.exam_prep_written_tasks x join cv on cv.id=x.content_version_id), items(akey,ord,ckey,wkey,skill,role,holdout) as (values
('p5_aw17_binomial_diagnostic',1,'P5BIN02-D01',null,'P5-BIN-02','diagnostic',true),('p5_aw17_binomial_diagnostic',2,'P5BIN03-D01',null,'P5-BIN-03','diagnostic',true),
('p5_bin02_learning',1,'P5BIN02-L01',null,'P5-BIN-02','learning',false),('p5_bin02_learning',2,'P5BIN02-L02',null,'P5-BIN-02','learning',false),('p5_bin02_learning',3,'P5BIN02-L03',null,'P5-BIN-02','learning',false),('p5_bin02_learning',4,null,'P5BIN02-W01','P5-BIN-02','written',false),
('p5_bin03_learning',1,'P5BIN03-L01',null,'P5-BIN-03','learning',false),('p5_bin03_learning',2,'P5BIN03-L02',null,'P5-BIN-03','learning',false),('p5_bin03_learning',3,'P5BIN03-L03',null,'P5-BIN-03','learning',false),('p5_bin03_learning',4,null,'P5BIN03-W01','P5-BIN-03','written',false),
('p5_bin02_retest',1,'P5BIN02-R01',null,'P5-BIN-02','retest',true),('p5_bin03_retest',1,'P5BIN03-R01',null,'P5-BIN-03','retest',true),
('p5_aw17_binomial_mixed',1,'P5BIN02-M01',null,'P5-BIN-02','mixed',true),('p5_aw17_binomial_mixed',2,'P5BIN03-M01',null,'P5-BIN-03','mixed',true))
insert into private.exam_prep_assessment_items(assessment_id,item_order,question_id,written_task_id,primary_skill_code,reserve_role,is_holdout)
select a.id,i.ord,m.question_id,w.id,i.skill,i.role,i.holdout from items i join a on a.assessment_key=i.akey left join m on m.content_key=i.ckey left join w on w.task_key=i.wkey
on conflict(assessment_id,item_order) do nothing;

update private.exam_prep_question_content_meta m set copyright_status='pass',qa_scope_status='pass',qa_math_status='pass',qa_language_status='pass',qa_technical_status='pass',diagnostic_rule_status=case when reserve_role='diagnostic' then 'approved' else 'not_applicable' end,lifecycle_state='approved',approved_at=now(),updated_at=now() from private.exam_prep_content_versions cv where cv.id=m.content_version_id and cv.content_version='p5_aw17_20_binomial_v1' and cv.status='draft';
update private.exam_prep_content_versions set status='approved',approved_at=now() where content_version='p5_aw17_20_binomial_v1' and status='draft';
update private.exam_prep_question_content_meta m set lifecycle_state=case when reserve_role='learning' then 'published' else 'reserve' end,exposure_state=case when reserve_role='learning' then 'released' else 'withheld' end,published_at=case when reserve_role='learning' then now() else null end,updated_at=now() from private.exam_prep_content_versions cv where cv.id=m.content_version_id and cv.content_version='p5_aw17_20_binomial_v1' and cv.status='approved';
update private.exam_prep_written_tasks w set lifecycle_state='published' from private.exam_prep_content_versions cv where cv.id=w.content_version_id and cv.content_version='p5_aw17_20_binomial_v1' and cv.status='approved';
update private.exam_prep_assessments a set status='published',approved_at=coalesce(a.approved_at,now()) from private.exam_prep_content_versions cv where cv.id=a.content_version_id and cv.content_version='p5_aw17_20_binomial_v1' and cv.status='approved';
update private.exam_prep_content_versions set status='published',published_at=now() where content_version='p5_aw17_20_binomial_v1' and status='approved';

do $$ declare v_program bigint; v_skill text; begin
select id into v_program from private.exam_prep_program_versions where program_key='math_as_p1_p5' and version_key='p1_p5_canonical_v1_0';
foreach v_skill in array array['P5-BIN-02','P5-BIN-03'] loop if not private.exam_prep_skill_content_ready_v1(v_program,'P5',v_skill) then raise exception 'Binomial skill not ready %',v_skill; end if; end loop;
if exists(select 1 from public.questions where book_ref like 'ExamPrep:P5:p5_aw17_20_binomial_v1:%' and is_active) then raise exception 'legacy activation residue'; end if;
if exists(select 1 from private.exam_prep_feature_config where program_key='math_as_p1_p5' and (rollout_state<>'off' or core_enabled or ai_enabled or mentor_enabled or not kill_switch)) then raise exception 'feature escaped fail-closed'; end if;
if exists(select 1 from private.exam_prep_feature_entitlements where entitlement_status='active') then raise exception 'active entitlement residue'; end if;
end $$;
commit;
